select jsonb_build_object(
 'identity',current_user='postgres' and session_user='postgres' and current_database()='postgres',
 'tables_rls',(select count(*)=6 and bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='ops' and c.relname=any(array['apify_launch_approvals','apify_launch_admissions','foundation_gateway_rate_windows','foundation_gateway_requests','foundation_gateway_leases','foundation_gateway_run_bindings']) and c.relkind='r'),
 'no_machine_table_grants',not exists(select 1 from information_schema.role_table_grants g where g.table_schema='ops' and g.table_name=any(array['apify_launch_approvals','apify_launch_admissions','foundation_gateway_rate_windows','foundation_gateway_requests','foundation_gateway_leases','foundation_gateway_run_bindings']) and g.grantee=any(array['anon','authenticated','api_agent','n8n_writer','PUBLIC'])),
 'rpc_shape',(select count(*)=9 and bool_and(p.prosecdef and 'search_path=""'=any(p.proconfig) and has_function_privilege('n8n_writer',p.oid,'EXECUTE') and not has_function_privilege('api_agent',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('authenticated',p.oid,'EXECUTE') and not exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee=0 and a.privilege_type='EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ops' and p.proname=any(array['get_apify_launch','authorize_apify_launch','reconcile_apify_launch','reject_apify_callback','foundation_gateway_admit','foundation_gateway_execute','foundation_gateway_status','foundation_gateway_read_context','foundation_gateway_complete_read'])),
 'owner_control_restricted',(select count(*)=2 and bool_and(not has_function_privilege('service_role',p.oid,'EXECUTE') and not has_function_privilege('n8n_writer',p.oid,'EXECUTE') and not has_function_privilege('api_agent',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('authenticated',p.oid,'EXECUTE') and not exists(select 1 from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where a.grantee=0 and a.privilege_type='EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='ops' and p.proname='foundation_gateway_provision'),
 'all_project_tables_rls',not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=any(array['app','ops','ingest']) and c.relkind='r' and not c.relrowsecurity),
 'all_views_invoker',not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=any(array['app','api','ops','ingest']) and c.relkind='v' and not coalesce(c.reloptions@>array['security_invoker=true'],false)),
 'gw01_closed',(select count(*)=1 and bool_and(w.closed_at is not null) from ops.worker_gateway_rate_windows w where w.window_id='76c2ad42-c094-4ba4-9a0b-566e19b97780'),
 'domain_auto_join_off',not exists(select 1 from app.allowed_domains),
 'baseline_counts',(select count(*) from app.competitors where company_code<>'C999')=285 and (select count(*) from app.competitor_accounts a join app.competitors c on c.id=a.competitor_id where c.company_code<>'C999')=1754,
 'forward_primary_key',(select count(*)=1 and bool_and(pg_get_constraintdef(c.oid)='PRIMARY KEY (namespace, window_id)') from pg_constraint c where c.conrelid='ops.foundation_gateway_rate_windows'::regclass and c.contype='p'),
 'forward_signatures',to_regprocedure('ops.foundation_gateway_provision(jsonb)') is not null and to_regprocedure('ops.foundation_gateway_provision(uuid,jsonb)') is not null,
 'forward_namespace',(select count(*)=3 and bool_and(pg_get_constraintdef(c.oid) like '%m03-foundation-dev%' or pg_get_constraintdef(c.oid) like '%zmotjsbzhzjvpelxvxlf%' or pg_get_constraintdef(c.oid) like '%dev%') from pg_constraint c where c.conrelid='ops.foundation_gateway_rate_windows'::regclass and c.contype='c' and (pg_get_constraintdef(c.oid) like '%m03-foundation-dev%' or pg_get_constraintdef(c.oid) like '%zmotjsbzhzjvpelxvxlf%' or pg_get_constraintdef(c.oid) like '%environment%')),
 'no_new_window',(select count(*)=1 and bool_and(window_id='df4f29ec-e2dc-4d82-a276-62a4e695e6f9' and closed_at is not null and close_count=1 and admitted_count=2) from ops.foundation_gateway_rate_windows),
 'schemas',jsonb_build_array('app','api','ops','ingest')
) as postcheck;
